head.script:
scwin.onpageload = function () {

};

scwin.trigger1_onclick = function (e) {
    scheduleCalendar1.gotoCalendar("20250501", { noSelectable: true });
};

scwin.trigger2_onclick = function (e) {
    scheduleCalendar1.gotoCalendar("20250101", { noSelectable: true });
};


scwin.trigger3_onclick = function (e) {
    scheduleCalendar1.gotoCalendar("20250301", { noSelectable: true });
};

scwin.scheduleCalendar1_onheaderbtnclick = function (buttonInfo) {
	console.log("버튼 종류: " + buttonInfo.buttonType);
	console.log("view 종류: " + buttonInfo.viewType);
	window.buttonType = buttonInfo.buttonType;
	window.viewType = buttonInfo.viewType;
	if (buttonInfo.buttonType == "next" || buttonInfo.buttonType == "prev" || buttonInfo.buttonType == "today"){
		console.log("날짜 정보: " + buttonInfo.date);
		window.date = buttonInfo.date;
	}

};

	scwin.getCurrentDate = function() {	
		const today = new Date(); // 현재 날짜를 가져옵니다.

		// 연도, 월, 일 추출
		const year = today.getFullYear(); // 4자리 연도
		const month = String(today.getMonth() + 1).padStart(2, '0'); // 1부터 12까지의 월
		const day = String(today.getDate()).padStart(2, '0'); // 1부터 31까지의 일

		// 원하는 형식으로 날짜를 반환합니다.
		return `${year}${month}${day}`;
	}
	scwin.checkVal1 = function() {
		const check1 = document.querySelectorAll('.fc-toolbar-title')[0].innerText == '2025년 5월'
		const check2 = document.querySelectorAll('.fc-highlight')[0].parentElement.parentElement.parentElement.innerText == '1일';

		return check1 && check2;
	}
	scwin.checkVal2 = function() {
		const check1 = window.buttonType == 'today';
		const check2 = window.viewType == 'dayGridMonth';
		const check3 = window.date == scwin.getCurrentDate();
		return check1 && check2 && check3;
	}

	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()","true");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('scheduleCalendar1').getElementsByTagName('button')[2].click()");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()","true");
		WebSquare.wUnit.addCommand("pause", "500");		

		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
        }
	scwin.unitTest()
